from typing import Any, Union, Optional

from taf.internal.aliasing import aliasing_scope
from taf.internal.robot_typecasts import time_to_seconds, to_boolean

from taf.hw.rf_attenuator.devices.jfw.jfw import LinearFadingScenario
from taf.hw.rf_attenuator.facade import AttenuatorFacade
from taf.hw.rf_attenuator.attenuator_class import Attenuator
from taf.hw.rf_attenuator.exceptions import NotEnoughParametersProvided, TooManyParametersProvided

Attenuation = Union[str, int, float]


class rf_attenuator(object):
    """Abstract Attenuator controlling library.

    The library can be set up with one of attenuator classes defined in `taf.config.testline.attenuator`:

    >>> from taf.hw.rf_attenuator import rf_attenuator
    >>> from taf.config.testline.attenuator import JFW
    >>> jfw_obj = JFW(ip_addr='1.2.3.4', port=23, attenuation_port_numbers=[1,2,3])
    >>> atten = rf_attenuator()
    >>> jfw_device = atten.setup_attenuator(jfw_obj)

    or directly as:

    >>> from taf.hw.rf_attenuator import rf_attenuator
    >>> atten = rf_attenuator()
    >>> jfw_device = atten.setup_attenuator(vendor='JFW', ip_addr='1.2.3.4', port=23, attenuation_port_numbers=[1,2,3])

    In both cases a default JFW model will be used. To set up a different model, one must provide `model` parameter:

    >>> jfw_obj = JFW(ip_addr='1.2.3.4', model='50PA-514',
    ...               port=23, attenuation_port_numbers=[1,2,3])

    or

    >>> jfw_device = atten.setup_attenuator(vendor='JFW', model='50PA-514',
    ...                                     ip_addr='1.2.3.4', port=23, attenuation_port_numbers=[1,2,3])

    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    lookup_handler, configured_attenuators = aliasing_scope(
        name=__name__, lookup_arg='attenuator_device', lookup_type=Attenuator
    )

    def __init__(self):
        self._facade = AttenuatorFacade()

    def setup_attenuator(self, attenuator=None, alias=None, **kwargs):
        # type: (Optional[Any], Optional[str], Any) -> Attenuator
        """
        Prepare library to work with a specified attenuator.

        :param Any attenuator: instance of an attenuator class defined in `taf.config.testline.attenuator`
        :param str alias: alias to be used in keywords
        :param kwargs: device specific parameters:

            Hytem, JFW, RadioRack, TopYoung, EUBUS, HBTE:
               str ip_addr: IP address
               int port: rf_attenuator's port for management, may be 23 or 30000
               list[int] attenuation_port_numbers: List of Port numbers on the rf_attenuator
               int min_attenuation: minimum attenuation value
               int max_attenuation: maximum attenuation value
               str vendor: vendor of the Attenuator, e.g. "JFW"
               Optional[str] model: model of the Attenuator, e.g. "50P-0033"
               Optional[str] version: version of the Attenuator, e.g. "0.2"
            JFW:
                mode: operational mode can be 'ports' or 'blocks'
                      Default mode is 'ports'
        :return Attenuator: configured rf_attenuator object
        :raises NotEnoughParametersProvided: if no rf_attenuator provided, neither object nor named parameters
        :raises TooManyParametersProvided: if rf_attenuator object and some of named parameters provided
        """
        required_kwargs = ['ip_addr', 'port', 'attenuation_port_numbers', 'vendor']
        if attenuator is None:
            if not set(required_kwargs).issubset(set(kwargs)):
                msg = 'All required parameters must be provided: {}'.format(', '.join(required_kwargs))
                raise NotEnoughParametersProvided(msg)
        else:
            if set(required_kwargs).intersection(set(kwargs)):
                msg = 'Must provide either attenuator object OR its parameters: {}'.format(', '.join(required_kwargs))
                raise TooManyParametersProvided(msg)
        configured_attenuator = self._facade.setup_attenuator(attenuator=attenuator, **kwargs)
        ports = attenuator.attenuator_ports if attenuator is not None else kwargs['attenuation_port_numbers']
        configured_attenuator.connect(ports=ports)
        self.configured_attenuators.add(configured_attenuator, alias)
        return configured_attenuator

    @lookup_handler.implicit_lookup
    def set_attenuation(self, port, value, confirm=False, attenuator_device=None, confirmation_delay=1):
        # type: (int, Attenuation, Optional[bool], Optional[Any], Optional[Union[int, float]]) -> None
        """
        Set attenuation.

        :param int port: rf_attenuator port to set the value on, requires calculate for some device,
            e.g. HBTE PAM-16X16-4-63-0.5, A3B4 port equals 51(3 + (4 - 1) * 16 = 51).
            Can also be an instance of `taf.config.testline.attenuator.AttenuationPort`
        :param Union[str,int,float] value: value to set in dB or %. It is string like '20dB', '10%' or int or float
        :param bool confirm: if true set value will be checked afterwards and if it is not set the exception is raised
        :param attenuator_device: attenuator to set the attenuation value
        :param Union[int,str] confirmation_delay: additional wait time before read_port_attenuation
        :raises AttenuationDifferentThanExpected: if confirm is true and set value doesn't match the real one
        :raises AttenuationSetError
        """
        if hasattr(port, "port_no"):
            port = port.port_no

        self._facade.set_port_attenuation(
            port=port,
            attenuation_value=value,
            confirm=to_boolean(confirm),
            attenuator=attenuator_device,
            confirmation_delay=time_to_seconds(confirmation_delay),
        )

    @lookup_handler.implicit_lookup
    def read_attenuation(self, port, attenuator_device=None):
        # type: (int, Optional[Any]) -> Union[int, float]
        """
        Read attenuation.

        :param port: rf_attenuator port to read the attenuation value, requires calculate for some device,
            e.g. HBTE PAM-16X16-4-63-0.5, A3B4 port equals 51(3 + (4 - 1) * 16 = 51).
            Can also be an instance of `taf.config.testline.attenuator.AttenuationPort`
        :param attenuator_device: attenuator to read the attenuation value
        :return attenuation value in db for the port
        :raises: AttenuationReadError If cannot read value of port, non-existing RF port
        """
        if hasattr(port, "port_no"):
            port = port.port_no

        return self._facade.read_port_attenuation(port=port, attenuator=attenuator_device)

    @lookup_handler.implicit_lookup
    def set_ports_attenuation(self, ports, values, confirm=False, confirmation_delay=1, attenuator_device=None):
        # type: (list[int], list[Attenuation], Optional[bool], Optional[Union[int, float]], Optional[Any]) -> None
        """
        Set multi-ports attenuation.

        :param list[int] ports: rf_attenuator port to set the value on, requires calculate for some device.
            e.g. HBTE PAM-16X16-4-63-0.5, A3B4 port equals 51(3 + (4 - 1) * 16 = 51)
        :param list[Union[str,int,float]] values: value to set in dB or %.
            It is string like '20dB', '10%' or int or float
        :param bool confirm: if true set value will be checked afterwards and if it is not set the exception is raised
        :param Union[int,str] confirmation_delay: additional wait time before read_port_attenuation
        :param attenuator_device: attenuator to set the attenuation value
        :raises AttenuationDifferentThanExpected: if confirm is true and set value doesn't match the real one
        :raises AttenuatorCmdError: Incorrect command syntax (TopYoung)
        :raises AttenuationSetError: Command failed
        """
        ports = [int(port) for port in ports]
        self._facade.set_ports_attenuation(
            ports=ports,
            attenuation_values=values,
            confirm=to_boolean(confirm),
            confirmation_delay=time_to_seconds(confirmation_delay),
            attenuator=attenuator_device,
        )

    @lookup_handler.implicit_lookup
    def read_ports_attenuation(self, ports, attenuator_device=None):
        # type: (list[int], Optional[Any]) -> list[float]
        """
        Read attenuation.

        :param list[int] ports: rf_attenuator port to read the attenuation value, requires calculate for some device.
            e.g. HBTE PAM-16X16-4-63-0.5, A3B4 port equals 51(3 + (4 - 1) * 16 = 51)
        :param attenuator_device: attenuator to read the attenuation value
        :return list of attenuation value in db for the port
        :raises AttenuationReadError: If cannot read value of port, non-existing RF port
        """
        ports = [int(port) for port in ports]
        return self._facade.read_ports_attenuation(ports=ports, attenuator=attenuator_device)

    @lookup_handler.implicit_lookup
    def set_linear_fading_scenario(self, port, start_value, end_value, interval, unit="M", attenuator_device=None):
        # type: (int, Attenuation, Attenuation, int, Optional[str], Optional[Any]) -> None
        """
        Set an linear fading scenario.
        This keyword is only available for JFW attenuator.

        :param int port: rf_attenuator port to set the value on. Can also be an instance of
            `taf.config.testline.attenuator.AttenuationPort`
        :param start_value: start attenuation value.
        :param end_value: end attenuation value.
        :param interval: interval time value.
        :param unit: interval time unit, "M"(milliseconds) or "S"(seconds), default is milliseconds.
        :param attenuator_device: attenuator to set the attenuation value.
        :return LinearFadingScenario: linear fading scenario object.
        :raises InvalidUnit: when unsupported time unit is used
        """
        if hasattr(port, "port_no"):
            port = port.port_no

        return self._facade.set_linear_fading_scenario(
            port=port,
            start_value=start_value,
            end_value=end_value,
            interval=interval,
            unit=unit,
            attenuator=attenuator_device,
        )

    @lookup_handler.implicit_lookup
    def set_ports_fading_attenuation(self, set_fading_scenarios, attenuator_device=None, timeout=2):
        # type: (list[LinearFadingScenario], Optional[Any], Optional[int]) -> None
        """
        Set ports fading attenuation by scenarios.

        .. note::
            This keyword is only available for JFW attenuator.

        :param list[LinearFadingScenario] set_fading_scenarios: ports' set fading attenuation scenarios.
            the element is created by "set_linear_fading_scenario" keyword.
        :param attenuator_device, instance of the connected attenuator.
        :param timeout, int time of the read
        :raises MultiPortsNotSupported: only for JFW50PA505
        """
        self._facade.set_ports_fading_attenuation(
            set_fading_scenarios,
            attenuator=attenuator_device,
            timeout=timeout
        )

    @lookup_handler.implicit_lookup
    def escape_command(self, attenuator_device=None):
        # type: (Optional[Any]) -> None
        """
        The escape command will cause the test system to stop processing and clear the connections command buffer.
        This command is useful for breaking out of remote commands that process over a period of time.
        (i.e. linear fading scenario).

        This command will not affect the buffered commands of other users.

        .. note::
            This keyword is only available for JFW attenuator with firmware version 3.x.x.

        :param attenuator_device: attenuator to escape the command
        """
        return self._facade.escape_command(attenuator=attenuator_device)


    @lookup_handler.implicit_lookup
    def disconnect(self, attenuator_device=None):
        """
        Disconnect from the device.

        :param attenuator_device: attenuator to escape the command
        """
        return self._facade.disconnect(attenuator=attenuator_device)
